import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, BoxGeometry, SphereGeometry, CircleGeometry, PointLight } = ctx.THREE;
  const palette = config.intent?.visualSpec?.colors ?? {};
  const ink = palette.ink ?? '#16161d';
  const paper = palette.paper ?? '#e8ecf2';
  const accent = palette.accent ?? '#ff2a38';
  const surface = palette.surface ?? '#0b0b10';

  const root = new Group();
  root.name = 'ornamental-divider';
  root.userData.handlers = {};

  const owned = [];
  const timelines = [];
  let disposed = false;

  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false,
    toneMapped: false
  });
  backdropMaterial.colorNode = mix(color(surface), color(ink), uv().y);

  const backdrop = new Mesh(new BoxGeometry(7, 6, 0.08), backdropMaterial);
  backdrop.name = 'machined-stage-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  owned.push(backdrop.geometry, backdrop.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0,
    toneMapped: false
  });

  const paperMaterial = new MeshStandardNodeMaterial({
    color: paper,
    metalness: 0.5,
    roughness: 0.58
  });

  const inkMaterial = new MeshStandardNodeMaterial({
    color: ink,
    metalness: 0.42,
    roughness: 0.62
  });

  const fallback = new Group();
  fallback.name = 'divider-fallback';

  const rule = new Mesh(new BoxGeometry(2.55, 0.035, 0.045), paperMaterial);
  rule.name = 'machined-rule';
  fallback.add(rule);

  const lowerRule = new Mesh(new BoxGeometry(2.55, 0.012, 0.06), inkMaterial);
  lowerRule.position.y = -0.035;
  lowerRule.position.z = 0.012;
  fallback.add(lowerRule);

  const jewel = new Mesh(new SphereGeometry(0.105, 24, 16), accentMaterial);
  jewel.name = 'center-signal-jewel';
  jewel.position.z = 0.055;
  fallback.add(jewel);

  const jewelCore = new Mesh(new SphereGeometry(0.042, 16, 12), new MeshBasicNodeMaterial({
    color: paper,
    toneMapped: false
  }));
  jewelCore.position.z = 0.085;
  fallback.add(jewelCore);

  const leftCap = new Mesh(new BoxGeometry(0.12, 0.11, 0.09), inkMaterial);
  leftCap.position.x = -1.28;
  fallback.add(leftCap);

  const rightCap = leftCap.clone();
  rightCap.position.x = 1.28;
  fallback.add(rightCap);

  root.add(fallback);
  owned.push(
    rule.geometry,
    lowerRule.geometry,
    jewel.geometry,
    jewelCore.geometry,
    leftCap.geometry,
    rightCap.geometry,
    paperMaterial,
    inkMaterial,
    accentMaterial,
    jewelCore.material
  );

  const contactShadowMaterial = new MeshBasicNodeMaterial({
    color: '#000000',
    transparent: true,
    opacity: 0.46,
    depthWrite: false
  });
  const contactShadow = new Mesh(
    new CircleGeometry(1.7, 48),
    contactShadowMaterial
  );
  contactShadow.name = 'divider-contact-shadow';
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -0.18, -0.12);
  contactShadow.scale.set(1.15, 0.22, 1);
  root.add(contactShadow);
  owned.push(contactShadow.geometry, contactShadow.material);

  const focusEdge = new Mesh(
    new BoxGeometry(2.82, 0.026, 0.018),
    accentMaterial
  );
  focusEdge.name = 'focus-accent-edge';
  focusEdge.position.set(0, 0.075, 0.08);
  root.add(focusEdge);

  const rim = new PointLight(accent, 0.72, 4.5, 2);
  rim.name = 'signal-rim-light';
  rim.position.set(0.4, 0.35, 1.25);
  root.add(rim);

  const fill = new PointLight(paper, 0.42, 4, 2);
  fill.name = 'paper-fill-light';
  fill.position.set(-1.8, 0.8, 1.5);
  root.add(fill);

  const loadedScenes = [];

  const loadMesh = (url) => {
    if (!url || !ctx.glbLoader?.loadGLB) return;

    ctx.glbLoader.loadGLB(url).then((gltf) => {
      if (disposed || !gltf?.scene) return;
      const scene = gltf.scene;
      scene.name = 'machined-divider-glb';
      fallback.visible = false;
      root.add(scene);
      loadedScenes.push(scene);
    }).catch(() => {
      // The authored fallback remains visible if the cached asset cannot be resolved.
    });
  };

  loadMesh(config.meshUrl);

  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(root.position, {
    y: 0.15,
    duration: 0.7,
    ease: 'power3.out'
  });
  timelines.push(hoverTimeline);

  const pressTimeline = gsap.timeline({ paused: true });
  pressTimeline
    .to(root.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'power2.out'
    })
    .to(root.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.38,
      ease: 'back.out(2)'
    });
  timelines.push(pressTimeline);

  root.userData.handlers.hover = (active = true) => {
    if (disposed) return;
    if (active) hoverTimeline.play();
    else hoverTimeline.reverse();
  };

  root.userData.handlers.click = () => {
    if (disposed) return;
    pressTimeline.restart();
    ctx.emit('hub-home.select', {
      node: 'ornamental-divider',
      source: 'hub-home'
    });
  };

  root.userData.handlers.focus = (active = true) => {
    if (disposed) return;
    gsap.to(accentMaterial, {
      opacity: active ? 0.95 : 0,
      duration: 0.2,
      ease: 'power2.out'
    });
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    root.traverse((object) => {
      if (!object.isMesh) return;
      if (object.geometry?.dispose) object.geometry.dispose();
      if (object.material) {
        const materials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        for (const material of materials) {
          if (material?.dispose) material.dispose();
        }
      }
    });

    for (const resource of owned) {
      if (resource?.dispose) resource.dispose();
    }

    for (const scene of loadedScenes) {
      if (scene.parent) scene.parent.remove(scene);
    }

    root.clear();
  };

  return root;
}
